public class Main {
    static class Livro implements Comparable<Livro> {
        private String titulo;
        private String autor;

        public Livro(String titulo, String autor) {
            this.titulo = titulo;
            this.autor = autor;
        }

        public String getTitulo() {
            return titulo;
        }

        public String getAutor() {
            return autor;
        }

        @Override
        public int compareTo(Livro outro) {
            return this.titulo.compareToIgnoreCase(outro.titulo);
        }
    }

    public static void main(String[] args) {
        List<Livro> livros = new ArrayList<>();
        livros.add(new Livro("O Relato do Caiaque Solitário", "Adoniram Britto"));
        livros.add(new Livro("1984", "George Orwell"));
        livros.add(new Livro("O Grande Gatsby", "F. Scott Fitzgerald"));

        livros.sort(null);

        livros.forEach(livro -> System.out.println(livro.getTitulo()));
    }
}
